    "minLength": 1,
    "maxLength": 300
   },
   "summary": {
    "type": "string",
    "minLength": 1,
    "maxLength": 4000
   }
  }
 },
 "suggested_pages": {
  "type": "array",
  "minItems": 1,
  "maxItems": 50,
  "items": {
   "type": "object",
   "additionalProperties": false,
   "required": [
    "title",
    "type",
    "category",
    "one_line_definition",
    "source_facts",
    "ai_organized",
    "ai_inferences",
    "related_pages",
    "open_questions",
    "source_evidence"
   ],
   "properties": {
    "title": {
     "type": "string",
     "minLength": 1,
     "maxLength": 300
    },
    "type": {
     "type": "string",
     "enum": [
      "concept",
