     ]
    },
    "one_line_definition": {
     "type": "string",
     "minLength": 1,
     "maxLength": 300
    },
    "source_facts": {
     "type": "array",
     "minItems": 1,
     "items": {
      "type": "object",
      "additionalProperties": false,
      "required": [
       "text",
       "evidenceIds"
      ],
      "properties": {
       "text": {
        "type": "string",
        "minLength": 1,
        "maxLength": 2000
       },
       "evidenceIds": {
        "type": "array",
        "minItems": 1,
        "items": {
         "type": "string",
         "minLength": 1,
         "maxLength": 64
        }
       }
      }
     }
    },
    "ai_organized": {
     "type": "array",
     "items": {
